<template>
 <ElConfigProvider namespace="kel">
  <section class="jobs-native">
   <header class="catalog-heading"><div><div class="title-line"><h1>{{executionMode?'Executions':'作业平台'}}</h1><span class="count">{{catalog?.total??rows.length}}</span></div><p>{{executionMode?'追踪每一次执行与设备结果。':'编排交付任务，追踪每一次执行。'}}</p></div><div class="actions"><KsButton v-if="!executionMode" :disabled="!canExecute" @click="emit('quickRun')"><LightningBolt :size="14"/>Quick Run</KsButton><KsButton v-if="!executionMode" type="primary" :disabled="!canCreate" @click="emit('create')"><Plus :size="14"/>创建 Flow</KsButton><KsButton v-if="executionMode" :loading="loading" @click="emit('refresh')">刷新</KsButton></div></header>
   <div class="viewbar"><div class="view-tabs" v-if="!executionMode"><button v-for="v in flowViews" :key="v.id" :class="{active:stateFilter===v.id||!stateFilter&&!v.id}" @click="emit('filter','state',v.id)">{{v.name}}<small v-if="v.count!==undefined">{{v.count}}</small></button></div><div v-else class="view-tabs"><button :class="{active:!stateFilter&&executionFilters?.attention!=='true'}" @click="emit('filter','state','');emit('extraFilter','attention','')">全部记录</button><button :class="{active:stateFilter==='RUNNING'}" @click="emit('filter','state','RUNNING')">运行中 <small v-if="summary">{{summary.states.RUNNING||0}}</small></button><button :class="{active:executionFilters?.attention==='true'}" @click="emit('filter','state','');emit('extraFilter','attention','true')">需要关注</button><button @click="emit('view','overview')">运行概况</button><button @click="emit('view','logs')">跨执行日志</button></div><div class="saved-views" v-if="!executionMode"><select v-if="savedViews?.length" aria-label="已保存视图" value="" @change="emit('applyView',value($event))"><option value="" disabled>已保存视图</option><option v-for="view in savedViews" :key="view.id" :value="view.id">{{view.name}}</option></select><button class="text-link" @click="viewName='';saveViewOpen=true">保存视图</button></div></div>
   <div v-if="executionMode&&summary" class="execution-summary"><span>{{summary.total}} 次执行</span><span class="success">{{summary.states.SUCCESS||0}} 成功</span><span class="failed">{{summary.states.FAILED||0}} 失败</span><span>{{summary.states.RUNNING||0}} 运行中</span><small>当前项目及来源/版本/时间范围 · 引擎状态与设备结果独立</small></div><div v-if="error" class="error" role="alert">{{error}}</div>
   <div class="filters">
    <KsInput v-model="search" :placeholder="executionMode?'搜索 Execution、Flow 或设备':'搜索 Flow 名称、ID 或 Namespace'" clearable/>
    <template v-if="!executionMode"><select :value="namespaceFilter||''" aria-label="Namespace筛选" @change="emit('extraFilter','namespace',value($event))"><option value="">所有 Namespace</option><option v-for="n in catalog?.namespaces||[]" :key="n">{{n}}</option></select><select :value="targetFilter||''" aria-label="目标类型筛选" @change="emit('extraFilter','target_type',value($event))"><option value="">所有目标类型</option><option value="server">GPU Server / Server</option><option value="switch">Switch</option><option value="both">Mixed</option></select></template>
    <select v-model="status" aria-label="状态筛选"><option value="">所有状态</option><option v-for="s in statuses" :key="s">{{s}}</option></select>
    <template v-if="executionMode"><select aria-label="执行来源" :value="executionFilters?.source||''" @change="emit('extraFilter','source',value($event))"><option value="">所有来源</option><option v-for="source in ['flows','quick-run','schedule','backfill','replay','ztp','retry','restart']" :key="source">{{source}}</option></select><select aria-label="实际执行通道" :value="executionFilters?.transport||''" @change="emit('extraFilter','transport',value($event))"><option value="">所有实际通道</option><option>AGENT</option><option>SSH</option></select><input type="datetime-local" aria-label="执行开始时间" :value="localTime(executionFilters?.since)" @change="emit('extraFilter','since',value($event))"/><input type="datetime-local" aria-label="执行结束时间" :value="localTime(executionFilters?.until)" @change="emit('extraFilter','until',value($event))"/></template>
    <button v-if="hasFilters" class="text-link" @click="emit('resetFilters')">清除筛选</button><span class="grow"/>
    <label v-if="!executionMode" class="source-search"><input type="checkbox" :checked="sourceSearch" @change="emit('extraFilter','source_search',($event.target as HTMLInputElement).checked?'true':'')"/>源码</label><KsButton size="small" :loading="loading" aria-label="刷新目录" @click="emit('refresh')"><Refresh :size="15"/></KsButton><KsButton size="small" @click="columnsOpen=!columnsOpen"><ViewColumnOutline :size="14"/>列</KsButton>
    <div v-if="columnsOpen" class="columns"><template v-if="executionMode"><label><input type="checkbox" v-model="showSource"/>来源</label><label><input type="checkbox" v-model="showTransport"/>通道</label><label><input type="checkbox" v-model="showStarted"/>开始时间</label></template><template v-else><label><input type="checkbox" v-model="showDescription"/>描述</label><label><input type="checkbox" v-model="showSchedule"/>触发方式</label><label><input type="checkbox" v-model="showUpdated"/>更新时间</label></template></div>
   </div>
   <div v-if="selected.length" class="selection"><b>已选择 {{selected.length}} 项</b><template v-if="!executionMode"><KsButton size="small" :disabled="!canEdit||loading" @click="emit('batch',selected,'enable')">启用所选</KsButton><KsButton size="small" :disabled="!canEdit||loading" @click="emit('batch',selected,'disable')">停用所选</KsButton></template><template v-else><KsButton v-for="a in [{id:'pause',label:'暂停所选'},{id:'resume',label:'继续所选'},{id:'kill',label:'终止所选'}]" :key="a.id" size="small" :disabled="!canExecute||loading" @click="emit('batch',selected,a.id)">{{a.label}}</KsButton></template><button class="text-link" @click="selected=[]">清除选择</button></div>
   <div class="catalog-table"><KsDataTable :data="visible" :total="catalog?.total??filtered.length" :loading="loading" :currentPage="catalog?Math.floor(catalog.offset/catalog.limit)+1:page" :pageSize="catalog?.limit||size" :rowKey="'id'" :fitHeight="true" :showPagination="executionMode?filtered.length>size:(catalog?.total||0)>(catalog?.limit||size)" :loadData="loadPage" :selectable="executionMode?canExecute:!!canEdit" @selection-change="v=>selected=v" @sort-change="sort=>emit('sort',sort.prop||'name',sort.order==='descending'?'desc':'asc')" noDataText="暂无符合条件的记录" @row-click="row=>emit('open',row)">
    <KsTableColumn prop="name" :label="executionMode?'Execution / Flow':'名称 / Flow ID'" :sortable="executionMode?false:'custom'" minWidth="240"><template #default="{row}"><div class="flow-name"><span class="flow-icon"><TransitConnectionVariant :size="18"/></span><div><button class="row-link" @click.stop="emit('open',row)">{{executionMode?(row.name||row.flow_name||row.id.slice(0,12)):row.name}}</button><code>{{executionMode?row.id.slice(0,12)+' · '+row.engine_flow_id:row.flow_id}}</code></div></div></template></KsTableColumn>
    <KsTableColumn :label="executionMode?'项目':'Namespace'" minWidth="190"><template #default="{row}"><span class="namespace">{{executionMode?row.project_id:row.namespace}}</span><small v-if="!executionMode&&showDescription">{{row.description||'—'}}</small></template></KsTableColumn>
    <KsTableColumn v-if="!executionMode" label="目标" width="105"><template #default="{row}"><span class="target-tag">{{row.target_type==='switch'?'Switch':row.target_type==='both'?'Mixed':'Server'}}</span></template></KsTableColumn>
    <KsTableColumn v-if="!executionMode&&showSchedule" label="触发方式" width="150"><template #default="{row}"><div v-if="row.triggers?.length" class="trigger-label"><ClockOutline :size="13"/><span :title="row.triggers.map(t=>`${t.id} · ${t.cron||t.type} · ${t.timezone||''} · ${t.enabled?'启用':'停用'}`).join('\n')">{{triggerLabel(row)}}</span></div><div v-else class="trigger-label"><CursorDefaultOutline :size="13"/>{{Object.keys(row.engine||{}).length?'手动':'未读取'}}</div></template></KsTableColumn>
    <KsTableColumn v-if="!executionMode" label="最近执行" minWidth="155"><template #default="{row}"><div v-if="row.recent_executions?.length" class="history-bars"><button v-for="run in [...row.recent_executions].reverse()" :key="run.id" :class="String(run.state).toLowerCase()" :title="`${run.state} · ${date(run.created_at)} · ${run.id}`" @click.stop="emit('execution',run.id)"/></div><small v-if="row.recent_execution">{{date(row.recent_execution.created_at)}}</small><small v-else>尚未执行</small></template></KsTableColumn>
    <KsTableColumn v-if="executionMode&&showSource" prop="source_module" label="来源" width="110"/>
    <KsTableColumn v-if="executionMode" label="目标 / 结果" width="150"><template #default="{row}">{{row.targets.length}} targets<small>{{row.targets.filter(t=>t.state==='SUCCESS').length}} success / {{row.targets.filter(t=>t.state==='FAILED').length}} failed</small></template></KsTableColumn>
    <KsTableColumn v-if="executionMode&&showTransport" label="模式 / 通道" width="145"><template #default="{row}">{{row.mode}}<small>Agent {{row.targets.filter(t=>t.actual_transport==='AGENT').length}} / SSH {{row.targets.filter(t=>t.actual_transport==='SSH').length}}</small></template></KsTableColumn>
    <KsTableColumn label="状态" width="105"><template #default="{row}"><KsExecutionStatus v-if="executionMode&&row.engine?.state?.current" :status="row.engine.state.current" size="small"/><span v-else :class="['flow-state',rowState(row).toLowerCase()]"><i/>{{({ENABLED:'已启用',DISABLED:'已停用',DRAFT:'草稿'} as any)[rowState(row)]||'未知'}}</span></template></KsTableColumn>
    <KsTableColumn v-if="executionMode&&showStarted" prop="created_at" label="开始时间" minWidth="160"><template #default="{row}">{{date(row.created_at)}}</template></KsTableColumn>
    <KsTableColumn v-if="!executionMode&&showUpdated" label="更新" minWidth="125"><template #default="{row}"><span :title="row.updated_by||''">{{row.updated_at?date(row.updated_at):'未记录'}}</span><small>rev {{row.revision}}</small></template></KsTableColumn>
    <KsTableColumn v-if="!executionMode" label="" width="66"><template #default="{row}"><KsButton size="small" :disabled="!canExecute||row.disabled||row.draft" aria-label="运行 Flow" @click.stop="emit('run',row)"><Play :size="14"/></KsButton></template></KsTableColumn>
   </KsDataTable></div>
   <footer><span>{{catalog?.total??filtered.length}} {{executionMode?'条已加载执行':'个 Flow'}}</span><span v-if="!executionMode">Namespace 隔离 · 版本化定义 · 授权执行</span><KsButton v-if="executionMode&&hasMore" size="small" :loading="loading" @click="emit('loadMore')">加载更早执行</KsButton></footer>
