  </section>
 </ElConfigProvider>
</template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {ElConfigProvider} from 'element-plus';
import KsDataTable from '../../vendor/kestra/design-system/components/Data/KsDataTable/KsDataTable.vue';import KsTableColumn from '../../vendor/kestra/design-system/components/Data/KsTable/KsTableColumn.vue';import KsButton from '../../vendor/kestra/design-system/components/Basic/KsButton/KsButton.vue';import KsInput from '../../vendor/kestra/design-system/components/Form/KsInput.vue';import KsExecutionStatus from '../../vendor/kestra/design-system/components/Data/KsExecutionStatus/KsExecutionStatus.vue';import KsDialog from '../../vendor/kestra/design-system/components/Feedback/KsDialog.vue';
import Plus from 'vue-material-design-icons/Plus.vue';import Play from 'vue-material-design-icons/Play.vue';import Refresh from 'vue-material-design-icons/Refresh.vue';import LightningBolt from 'vue-material-design-icons/LightningBolt.vue';import TransitConnectionVariant from 'vue-material-design-icons/TransitConnectionVariant.vue';import ViewColumnOutline from 'vue-material-design-icons/ViewColumnOutline.vue';import ClockOutline from 'vue-material-design-icons/ClockOutline.vue';import CursorDefaultOutline from 'vue-material-design-icons/CursorDefaultOutline.vue';
const props=defineProps<{summary?:any;columns?:string;tablePage?:number;tableSize?:number;executionFilters?:Record<string,string>;catalog?:any;sourceSearch?:boolean;canEdit?:boolean;namespaceFilter?:string;targetFilter?:string;rows:any[];executionMode:boolean;loading:boolean;error:string;canCreate:boolean;canExecute:boolean;hasMore:boolean;query:string;stateFilter:string;savedViews?:{id:string;name:string}[]}>();
const emit=defineEmits(['refresh','quickRun','create','open','run','edit','loadMore','filter','page','batch','extraFilter','execution','view','sort','resetFilters','saveView','applyView']);
const page=ref(props.tablePage||1),size=ref(props.tableSize||10),selected=ref<any[]>([]),columnsOpen=ref(false),showDescription=ref(true),showSchedule=ref(true),showUpdated=ref(true),showSource=ref(true),showTransport=ref(true),showStarted=ref(true),saveViewOpen=ref(false),viewName=ref('');
const value=(e:Event)=>(e.target as HTMLInputElement).value,date=(v:any)=>v&&Number.isFinite(Date.parse(v))?new Date(v).toLocaleString():'—';const localTime=(v?:string)=>{if(!v)return '';const d=new Date(v);if(Number.isNaN(d.getTime()))return '';return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
const search=computed({get:()=>props.query,set:v=>emit('filter','q',v)}),status=computed({get:()=>props.stateFilter,set:v=>emit('filter','state',v)}),rowState=(r:any)=>props.executionMode?r.engine?.state?.current||r.error_code||'unknown':!Object.keys(r.engine||{}).length?'unknown':r.draft?'DRAFT':r.disabled?'DISABLED':'ENABLED';
const statuses=computed(()=>props.executionMode?[...new Set(props.rows.map(rowState))]:['ENABLED','DRAFT','DISABLED','unknown']);const flowViews=computed(()=>[{id:'',name:'全部 Flows',count:props.catalog?.state_counts?.ALL},{id:'ENABLED',name:'已启用',count:props.catalog?.state_counts?.ENABLED},{id:'DRAFT',name:'草稿',count:props.catalog?.state_counts?.DRAFT}]);
const hasFilters=computed(()=>!!(props.query||props.stateFilter||props.namespaceFilter||props.targetFilter||props.sourceSearch||Object.values(props.executionFilters||{}).some(Boolean)));const filtered=computed(()=>props.catalog?props.rows:props.rows.filter(r=>(!status.value||rowState(r)===status.value)&&JSON.stringify([r.id,r.name,r.flow_name,r.namespace,r.flow_id,r.engine_flow_id,r.source_module]).toLowerCase().includes(search.value.toLowerCase()))),visible=computed(()=>props.catalog?props.rows:filtered.value.slice((page.value-1)*size.value,page.value*size.value));
function triggerLabel(row:any){const t=row.triggers[0];return (t.enabled?(t.cron||t.type.split('.').at(-1)):'已停用')+(row.triggers.length>1?` +${row.triggers.length-1}`:'')}
function loadPage(p:{page:number;size:number}){if(props.catalog)emit('page',p.page,p.size);else{page.value=p.page;size.value=p.size;emit('extraFilter','exec_page',String(p.page));emit('extraFilter','exec_size',String(p.size))}}
watch(()=>[props.executionMode,props.query,props.stateFilter,props.namespaceFilter,props.targetFilter],()=>{page.value=1;selected.value=[]});watch(()=>props.rows,()=>selected.value=[]);
const columnRefs={description:showDescription,schedule:showSchedule,updated:showUpdated,source:showSource,transport:showTransport,started:showStarted};
watch(()=>props.columns,value=>{let names:string[]|null=null;try{if(value)names=JSON.parse(value)}catch{}for(const [key,ref] of Object.entries(columnRefs))ref.value=names?names.includes(key):true},{immediate:true});
watch(Object.values(columnRefs),()=>{const selected=JSON.stringify(Object.entries(columnRefs).filter(([,v])=>v.value).map(([k])=>k));if(selected!==props.columns)emit('extraFilter','columns',selected)});
watch(()=>[props.tablePage,props.tableSize],()=>{page.value=props.tablePage||1;size.value=props.tableSize||10});
</script>
