<style scoped>.execution-summary{display:flex;gap:20px;align-items:center;font-size:11px;border-bottom:1px solid var(--ks-border-default);padding:14px 0}.execution-summary small{margin-left:auto;font-size:10px;color:var(--ks-text-secondary)}.execution-summary .success{color:var(--ks-text-success)}.execution-summary .failed{color:var(--ks-text-error)}</style>
